use std::fs

fn find(keys: Vec<int>, k: int) -> int {
    let mut r = -1
    for i in 0..keys.len() {
        if keys[i] == k {
            r = i
        }
    }
    r
}

fn num(s: string) -> int {
    s.parse::<int>().unwrap_or(0)
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut keys: Vec<int> = []
    let mut vals: Vec<int> = []
    let mut cap = 1
    let mut first = true
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().map(|s| s.to_string()).collect()
        if parts.len() == 0 || parts[0] == "" {
            continue
        }
        if first {
            cap = num(parts[0])
            first = false
            continue
        }
        let cmd = parts[0]
        if cmd == "put" {
            let k = num(parts[1])
            let v = num(parts[2])
            let i = find(keys, k)
            if i >= 0 {
                keys.remove(i)
                vals.remove(i)
            }
            keys.push(k)
            vals.push(v)
            let n: int = keys.len() as int
            if n > cap {
                let old = keys[0]
                keys.remove(0)
                vals.remove(0)
                println("evict ${old}")
            }
        } else if cmd == "get" {
            let k = num(parts[1])
            let i = find(keys, k)
            if i < 0 {
                println("-1")
            } else {
                let v = vals[i]
                keys.remove(i)
                vals.remove(i)
                keys.push(k)
                vals.push(v)
                println("${v}")
            }
        } else if cmd == "keys" {
            if keys.len() == 0 {
                println("<empty>")
            } else {
                let mut out: Vec<string> = []
                let mut j = keys.len()
                while j > 0 {
                    j -= 1
                    out.push("${keys[j]}")
                }
                println(out.join(" "))
            }
        }
    }
}

